 function spawnAmbientPeople(){const routes=[[[-20,-4.55],[20,-4.55],[20,4.55],[-20,4.55]],[[-20,4.55],[20,4.55],[20,-4.55],[-20,-4.55]],[[-4.55,-20],[-4.55,20],[4.55,20],[4.55,-20]],[[4.55,-20],[4.55,20],[-4.55,20],[-4.55,-20]],[[ -20,-4.55],[-4.55,-4.55],[-4.55,-20],[4.55,-20],[4.55,-4.55],[20,-4.55]],[[20,4.55],[4.55,4.55],[4.55,20],[-4.55,20],[-4.55,4.55],[-20,4.55]]];const people=[['Clara','#bd7861'],['Mateo','#6689a4'],['Sofi','#b58b5e'],['Dani','#8d789e'],['Pablo','#668a75'],['Nora','#bd7180']];ambientPeople=people.map(([name,color],i)=>{const a=makeActor(name,color,false),route=routes[i];a.children[a.children.length-1].visible=false;a.position.set(route[0][0],0,route[0][1]);a.userData.route=route;a.userData.waypoint=1;a.userData.phase=i*1.9;scene.add(a);return a})}
  function makeCar(axis,road,direction,coordinate,color){const lane=road+(direction>0?-1.8:1.8),root=new THREE.Group(),paint=mat(color),glass=mat('#a9c5c6'),tire=mat('#24292d'),rim=mat('#9ca4a0'),lamp=mat('#f6df9e'),tail=mat('#d95046');box(root,0,.46,0,1.58,.48,2.9,paint);box(root,0,.79,-.08,1.3,.36,1.55,glass);box(root,0,1.01,.92,1.5,.1,.2,paint);for(const side of [-1,1]){box(root,side*.79,.42,1.31,.07,.17,.22,lamp);box(root,side*.79,.42,-1.31,.07,.17,.22,tail);for(const end of [-1,1]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.27,.27,.15,10),tire);wheel.rotation.z=Math.PI/2;wheel.position.set(side*.78,.29,end*.9);root.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,.16,8),rim);hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);root.add(hub)}}root.position.set(axis==='x'?coordinate:lane,.04,axis==='x'?lane:coordinate);scene.add(root);const car={root,axis,direction,coordinate,lane,road,speed:3.2+(Math.abs(road)%2)*.3,stopped:false,alarmed:false};root.rotation.y=axis==='x'?(direction>0?Math.PI/2:-Math.PI/2):(direction>0?0:Math.PI);return car}
  function spawnTraffic(){const specs=[['x',0,1,-35,'#d6755d'],['x',0,-1,35,'#5d8195'],['z',0,1,-10,'#d2ad54'],['z',0,-1,35,'#638c72'],['x',-25,1,-40,'#9678a8'],['z',25,-1,40,'#6d9c9b']];traffic=specs.map(spec=>makeCar(...spec))}

