import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true,timeout:30000});
const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
await page.route('http://localhost:3002/**',async route=>{const response=await route.fetch();let body=await response.text();body=body.replace('</script></body></html>',`window.__trafficDebug=()=>({player:player.position.toArray(),suspicion,traffic:traffic.map(c=>({axis:c.axis,coordinate:c.coordinate,lane:c.lane,stopped:c.stopped,alarmed:c.alarmed}))});window.__placeCar=(x)=>{traffic[0].coordinate=x;traffic[0].root.position.x=x};</script></body></html>`);await route.fulfill({response,body})});
await page.goto('http://localhost:3002',{waitUntil:'networkidle',timeout:45000});
await page.locator('#start').click();
await page.waitForTimeout(1400);
const idle=await page.evaluate(()=>window.__trafficDebug());
await page.evaluate(()=>window.__placeCar(-9.5));
const joy=await page.locator('#joystick').boundingBox();
const cx=joy.x+joy.width/2,cy=joy.y+joy.height/2;
await page.mouse.move(cx,cy);await page.mouse.down();await page.mouse.move(cx,cy-32,{steps:10});
await page.waitForTimeout(1900);
const crossing=await page.evaluate(()=>window.__trafficDebug());
await page.mouse.up();
console.log(JSON.stringify({idle,crossing,errors},null,2));
await browser.close();
EOF
