 function say(text){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=text;shell.append(e);clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.remove(),2500)}
let dialogueTimer;
function showSceneDialogue(speaker,text,buttonLabel,onContinue){const box=document.querySelector('#sceneDialogue');clearTimeout(dialogueTimer);box.innerHTML=`<div class="scene-dialogue-head">${speaker}</div><div class="scene-dialogue-text">${text}</div>${buttonLabel?`<button type="button">${buttonLabel}</button>`:''}`;box.classList.remove('hidden');const button=box.querySelector('button');if(button)button.onclick=()=>{box.classList.add('hidden');if(onContinue)onContinue()};else dialogueTimer=setTimeout(()=>box.classList.add('hidden'),2800)}
function showChoices(title,desc,answers,correct,onChoose){const box=document.querySelector('#taskModal');document.querySelector('#sceneDialogue').classList.add('hidden');box.innerHTML=`<div class="eyebrow">${title.toUpperCase()}</div><h2>${desc}</h2><div class="choices">${answers.map((a,i)=>`<button class="choice" data-answer="${i}"><b>0${i+1}</b>${a}</button>`).join('')}</div>`;box.classList.remove('hidden');activeTask=true;box.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{const answer=+b.dataset.answer;box.classList.add('hidden');activeTask=false;onChoose(answer===correct)})}
function beginInteraction(speaker,line,title,desc,answers,correct,onChoose){activeTask=true;showSceneDialogue(speaker,line,'RESPONDER',()=>showChoices(title,desc,answers,correct,onChoose))}

