import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true,timeout:30000});
for (const answer of [0,1]) {
  const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
  await page.route('http://localhost:3002/**',async route=>{
    const response=await route.fetch();
    let body=await response.text();
    body=body.replace('</script></body></html>',`window.__positionNearMara=()=>{player.position.set(-13,0,-5);crew.forEach(a=>a.position.set(30,0,30));traffic.forEach(c=>{c.coordinate=40;c.root.position.set(c.axis==='x'?40:c.lane,.04,c.axis==='x'?c.lane:40)});};</script></body></html>`);
    await route.fulfill({response,body});
  });
  await page.goto('http://localhost:3002',{waitUntil:'networkidle',timeout:45000});
  await page.locator('#start').click();
  await page.evaluate(()=>window.__positionNearMara());
  await page.evaluate(()=>interact());
  await page.waitForTimeout(100);
  const opened=await page.locator('#taskModal').isVisible();
  const initial=await page.evaluate(()=>window.__gameDebug());
  const modalText=opened?await page.locator('#taskModal').innerText():'';
  if(opened) await page.locator(`#taskModal [data-answer="${answer}"]`).click();
  await page.waitForTimeout(250);
  const post=await page.evaluate(()=>window.__gameDebug());
  const followup=await page.locator('#taskModal').isVisible().catch(()=>false);
  console.log(JSON.stringify({answer,opened,modalText,initial:{player:initial.player,suspicion:initial.suspicion,activeTask:initial.activeTask},post:{trust:post.trust,suspicion:post.suspicion,activeTask:post.activeTask,dialogue:post.dialogue},followup,errors}));
  await page.close();
}
await browser.close();

