import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true,timeout:30000});
const page=await browser.newPage({viewport:{width:1280,height:800}});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
await page.route('http://localhost:3002/**',async route=>{
  const response=await route.fetch();
  let body=await response.text();
  body=body.replace('</script></body></html>',`window.__runCollisionTests=()=>{
    const actors=[player,...crew,...civilians,...ambientPeople];
    actors.forEach((a,i)=>a.position.set(30+i*2,0,30));
    traffic.forEach(c=>{c.coordinate=40;c.root.position.set(c.axis==='x'?40:c.lane,.04,c.axis==='x'?c.lane:40);c.stopped=false});
    player.position.set(0,0,0);crew[0].position.set(.95,0,0);
    const actorBefore=player.position.x;moveActor(player,1,0,.1,2.25);const actorAfter=player.position.x;
    actors.forEach((a,i)=>a.position.set(30+i*2,0,30));
    player.position.set(0,0,-1.8);traffic[0].coordinate=1;traffic[0].lane=-1.8;traffic[0].root.position.set(1,.04,-1.8);
    const carBlockBefore=player.position.x;moveActor(player,1,0,.1,2.25);const carBlockAfter=player.position.x;
    traffic.forEach(c=>{c.coordinate=40;c.root.position.set(c.axis==='x'?40:c.lane,.04,c.axis==='x'?c.lane:40);c.stopped=false});
    const a=traffic[0],b=traffic[2];a.coordinate=-2.2;a.root.position.set(-2.2,.04,a.lane);b.coordinate=-2.2;b.root.position.set(b.lane,.04,-2.2);a.speed=b.speed=3.2;
    updateTraffic(.1);const crossing={aStopped:a.stopped,bStopped:b.stopped,aCoordinate:a.coordinate,bCoordinate:b.coordinate};
    const route={actorBefore,actorAfter,carBlockBefore,carBlockAfter};
    return {route,crossing,suspicion};
  };</script></body></html>`);
  await route.fulfill({response,body});
});
await page.goto('http://localhost:3002',{waitUntil:'networkidle',timeout:45000});
await page.locator('#start').click();
console.log(JSON.stringify({result:await page.evaluate(()=>window.__runCollisionTests()),errors},null,2));
await browser.close();

