+3);car.obstructionAlarmed=true}}else car.obstructionAlarmed=false;if(!plan.stopped){car.coordinate+=car.direction*car.speed*dt;if(car.coordinate>49)car.coordinate=-49;if(car.coordinate< -49)car.coordinate=49}car.root.position.set(car.axis==='x'?car.coordinate:car.lane,.04,car.axis==='x'?car.lane:car.coordinate)}}
