import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true,timeout:30000});
const page=await browser.newPage({viewport:{width:1280,height:800}});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
await page.route('http://localhost:3002/**',async route=>{
  const response=await route.fetch();
  let body=await response.text();
  body=body.replace('</script></body></html>',`window.__extraTest=()=>{
    const actors=[player,...crew,...civilians,...ambientPeople];
    actors.forEach((a,i)=>a.position.set(30+i*2,0,30));
    traffic.forEach(c=>{c.coordinate=40;c.root.position.set(c.axis==='x'?40:c.lane,.04,c.axis==='x'?c.lane:40);c.stopped=false;c.obstructionAlarmed=false});
    const car=traffic[0];car.coordinate=-7.5;car.root.position.x=-7.5;player.position.set(-5.25,0,-1.8);
    const crossBefore=suspicion;updateTraffic(.1);const crossAfter=suspicion;const crossStopped=car.stopped;
    car.obstructionAlarmed=false;car.coordinate=-2.5;car.root.position.x=-2.5;player.position.set(0,0,-1.8);
    const blockBefore=suspicion;updateTraffic(.1);const blockOnce=suspicion;updateTraffic(.1);const blockRepeated=suspicion;
    ambientPeople.forEach((a,i)=>a.position.set(30+i*2,0,30));
    const [a,b]=ambientPeople;a.position.set(-1,0,0);b.position.set(1,0,0);
    a.userData.route=[[10,0],[-10,0]];a.userData.waypoint=0;a.userData.avoidance=null;
    b.userData.route=[[-10,0],[10,0]];b.userData.waypoint=0;b.userData.avoidance=null;
    const startA=a.position.clone(),startB=b.position.clone();let minGap=Infinity;
    for(let i=0;i<320;i++){updateAmbientPeople(.05,i*.05);minGap=Math.min(minGap,a.position.distanceTo(b.position))}
    return {crosswalk:{before:crossBefore,after:crossAfter,stopped:crossStopped},outside:{before:blockBefore,once:blockOnce,repeated:blockRepeated},npc:{startA:startA.toArray(),endA:a.position.toArray(),startB:startB.toArray(),endB:b.position.toArray(),minGap,stuckA:a.userData.avoidance?.stuck,stuckB:b.userData.avoidance?.stuck}};
  };</script></body></html>`);
  await route.fulfill({response,body});
});
await page.goto('http://localhost:3002',{waitUntil:'networkidle',timeout:45000});
await page.locator('#start').click();
console.log(JSON.stringify({result:await page.evaluate(()=>window.__extraTest()),errors},null,2));
await browser.close();

